import json
from collections import Counter

# Load demos
with open('/home/USER/runs/paper/qwen-hpl-u1-turns/frozen/seen/play/users/u048/system/state/workspace/programs/task-d2e27133.json', 'r') as f:
    demos = json.load(f)

# Collect value pairs in input and what they map to
value_mappings = {}
for demo in demos:
    for r_in, r_out in zip(demo['input'], demo['output']):
        if len(set(r_in)) > 1:
            vals = set(r_in)
            pair = tuple(sorted(vals))
            if pair not in value_mappings:
                # Find the mapping for this pair
                pattern = {}
                for v in vals:
                    # Find first row where v appears
                    for c, v_in in enumerate(r_in):
                        if v_in == v:
                            pattern[v] = r_out[c]
                            break
                value_mappings[pair] = pattern

print("Value pair mappings:")
for pair, mapping in value_mappings.items():
    print(f"  {pair}: {mapping}")

# Now look at Demo 2 rows
print()
print("Demo 2, rows with different counts:")
for in_row, out_row in zip(demo['input'][2], demo['output'][2]):
    inp, out = in_row, out_row
    counts = Counter(inp)
    print(f"  Counts: {dict(counts)}, min_count={min(counts.values())}, max_count={max(counts.values())}")
